-- Plan 10: the level ladder now takes hours (xp to next level 200, 400, 900, 2200, 4400; was 10, 15, 20, 30, 40).
-- Every existing avatar keeps its earned xp: total = the xp the old ladder had spent up to its level plus the leftover.
-- Its level is recalculated on the new ladder, the leftover is what remains, and max health follows the new level.
-- Coins, gear and place are untouched. Dead avatars (hp 0) stay dead. Level 6 under the new ladder keeps no leftover xp.
UPDATE characters SET
  xp = CASE WHEN (CASE level WHEN 1 THEN 0 WHEN 2 THEN 10 WHEN 3 THEN 25 WHEN 4 THEN 45 WHEN 5 THEN 75 WHEN 6 THEN 115 END + xp) >= 8100 THEN 0 ELSE (CASE level WHEN 1 THEN 0 WHEN 2 THEN 10 WHEN 3 THEN 25 WHEN 4 THEN 45 WHEN 5 THEN 75 WHEN 6 THEN 115 END + xp) - (CASE WHEN (CASE level WHEN 1 THEN 0 WHEN 2 THEN 10 WHEN 3 THEN 25 WHEN 4 THEN 45 WHEN 5 THEN 75 WHEN 6 THEN 115 END + xp) >= 8100 THEN 8100 WHEN (CASE level WHEN 1 THEN 0 WHEN 2 THEN 10 WHEN 3 THEN 25 WHEN 4 THEN 45 WHEN 5 THEN 75 WHEN 6 THEN 115 END + xp) >= 3700 THEN 3700 WHEN (CASE level WHEN 1 THEN 0 WHEN 2 THEN 10 WHEN 3 THEN 25 WHEN 4 THEN 45 WHEN 5 THEN 75 WHEN 6 THEN 115 END + xp) >= 1500 THEN 1500 WHEN (CASE level WHEN 1 THEN 0 WHEN 2 THEN 10 WHEN 3 THEN 25 WHEN 4 THEN 45 WHEN 5 THEN 75 WHEN 6 THEN 115 END + xp) >= 600 THEN 600 WHEN (CASE level WHEN 1 THEN 0 WHEN 2 THEN 10 WHEN 3 THEN 25 WHEN 4 THEN 45 WHEN 5 THEN 75 WHEN 6 THEN 115 END + xp) >= 200 THEN 200 ELSE 0 END) END,
  level = (CASE WHEN (CASE level WHEN 1 THEN 0 WHEN 2 THEN 10 WHEN 3 THEN 25 WHEN 4 THEN 45 WHEN 5 THEN 75 WHEN 6 THEN 115 END + xp) >= 8100 THEN 6 WHEN (CASE level WHEN 1 THEN 0 WHEN 2 THEN 10 WHEN 3 THEN 25 WHEN 4 THEN 45 WHEN 5 THEN 75 WHEN 6 THEN 115 END + xp) >= 3700 THEN 5 WHEN (CASE level WHEN 1 THEN 0 WHEN 2 THEN 10 WHEN 3 THEN 25 WHEN 4 THEN 45 WHEN 5 THEN 75 WHEN 6 THEN 115 END + xp) >= 1500 THEN 4 WHEN (CASE level WHEN 1 THEN 0 WHEN 2 THEN 10 WHEN 3 THEN 25 WHEN 4 THEN 45 WHEN 5 THEN 75 WHEN 6 THEN 115 END + xp) >= 600 THEN 3 WHEN (CASE level WHEN 1 THEN 0 WHEN 2 THEN 10 WHEN 3 THEN 25 WHEN 4 THEN 45 WHEN 5 THEN 75 WHEN 6 THEN 115 END + xp) >= 200 THEN 2 ELSE 1 END);

UPDATE characters SET
  max_hp = (CASE level WHEN 1 THEN 70 WHEN 2 THEN 80 WHEN 3 THEN 92 WHEN 4 THEN 106 WHEN 5 THEN 122 WHEN 6 THEN 140 END)
    + (CASE armor WHEN 'leather' THEN 12 WHEN 'chain' THEN 24 WHEN 'plate' THEN 40 ELSE 0 END),
  hp = MIN(hp, (CASE level WHEN 1 THEN 70 WHEN 2 THEN 80 WHEN 3 THEN 92 WHEN 4 THEN 106 WHEN 5 THEN 122 WHEN 6 THEN 140 END)
    + (CASE armor WHEN 'leather' THEN 12 WHEN 'chain' THEN 24 WHEN 'plate' THEN 40 ELSE 0 END));
